function defineBuiltin(
  name: string,
  supportedArguments: readonly string[],
  compatibilityLevel: "api" | "shape" | "numeric" | "behavioral",
  implementation: BuiltinDefinition["implementation"],
  kind: BuiltinDefinition["kind"] = "regular",
  resultVisibility: BuiltinDefinition["resultVisibility"] = "visible",
): BuiltinDefinition {
  return definePackageBuiltin(
    "base",
    name,
    supportedArguments,
    compatibilityLevel,
    implementation,
    resultVisibility,
    kind,
  );
}

function definePackageBuiltin(
  packageName: string,
  name: string,
  supportedArguments: readonly string[],
  compatibilityLevel: "api" | "shape" | "numeric" | "behavioral",
  implementation: BuiltinDefinition["implementation"],
  resultVisibility: BuiltinDefinition["resultVisibility"] = "visible",
  kind: BuiltinDefinition["kind"] = "regular",
): BuiltinDefinition {
  return {
    package: packageName,
    name,
    kind,
    resultVisibility,
    metadata: {
      package: packageName,
      name,
      compatibilityLevel,
      referenceVersion: "R 4.6.x documented behavior",
      supportedArguments,
      unsupportedBehavior:
        packageName === "graphics"
          ? ["non-browser devices and graphical parameters outside the command subset"]
          : packageName === "grDevices"
            ? ["color conversion, spline palettes, and devices beyond the documented subset"]
            : packageName === "utils"
              ? [
                  "desktop data-view windows, package-description enumeration, and sessionInfo print/toLatex methods",
                ]
              : ["attributes beyond basic type/length"],
    },
    implementation,
  };
}

function withBuiltinFormals(
  definition: BuiltinDefinition,
  formals: readonly {
    readonly name: string;
    readonly defaultValue?: AstNode;
  }[],
): BuiltinDefinition {
  return {
    ...definition,
    formals: Object.freeze(
      formals.map((formal) => ({
        name: formal.name,
        ...(formal.defaultValue === undefined ? {} : { defaultValue: formal.defaultValue }),
        span: SYNTHETIC_SPAN,
      })),
    ),
  };
}

function debugFunctionFormals(): readonly {
  readonly name: string;
  readonly defaultValue?: AstNode;
}[] {
  return [
    { name: "fun" },
    { name: "text", defaultValue: { kind: "StringLiteral", value: "", span: SYNTHETIC_SPAN } },
    { name: "condition", defaultValue: nullAst() },
    { name: "signature", defaultValue: nullAst() },
  ];
}

